"""Publish the reproducible walking coverage audit without inventing exits."""
from pathlib import Path
from collections import Counter,defaultdict
import json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT.parent/'output/zone-crossings-70959'

def main():
 inventory=json.loads((OUT/'inventory.json').read_text())
 audit=json.loads((OUT/'coverage-audit.json').read_text())
 withheld=len(json.loads((ROOT/'tools/data/crossing-handoff-review.json').read_text())['handoffs'])
 edges=inventory['crossings'];maps=inventory['maps'];pairs=defaultdict(list)
 for edge in edges:pairs[tuple(sorted((edge['a']['mapID'],edge['b']['mapID'])))].append(edge)
 counts=Counter(e['source'] for e in edges)
 text=['# Walking connection coverage — build 70959','',
 'Generated by `python tools/report_walking_coverage.py` after rebuilding the native data. These are terrain/floor-supported routing links, not a live-client collision or availability guarantee.','',
 f"Bundled: **{len(edges)} links across {sum(a!=b for a,b in pairs)} distinct zone pairs**, including {counts['road-boundary']} road-boundary, {counts['dry-terrain-boundary']} dry-ground boundary and {counts['native-wmo-floor']+counts['native-model-floor']} native structure links. Same-zone structure links are counted separately from zone pairs.",'',
 f'Native ownership boundaries are checked against dry, permitted connectors and grounded approaches. The review withheld {withheld} exact handoffs that lacked approach evidence. Ownership chunks can meet across mountains, at sea, or on different floors. These adjacencies need independent evidence of a passage.','',
 '## Bundled connections','', '| Zones | Links | Evidence |','| --- | ---: | --- |']
 for (a,b),rows in sorted(pairs.items(),key=lambda p:(maps[str(p[0][0])]['name'],maps[str(p[0][1])]['name'])):
  names=f"{maps[str(a)]['name']} ↔ {maps[str(b)]['name']}" if a!=b else maps[str(a)]['name']+' (internal passages)'
  text.append(f"| {names} | {len(rows)} | {', '.join(sorted({e['source'] for e in rows}))} |")
 missing=[p for p in audit['pairs'] if (p['a'],p['b']) not in pairs]
 text+=['','## Ownership boundaries without a certified walking exit','',
 'These candidates were inspected by the boundary audit. Zero safe samples is a rejection, not permission to draw a straight connector. Some are not physically adjacent within their zone map bounds. Tunnel/transport candidates require independent evidence.','',
 '| Areas sharing native ownership chunks | Boundary chunks | Safe dry samples |', '| --- | ---: | ---: |']
 for p in sorted(missing,key=lambda p:p['names']):
  text.append(f"| {' ↔ '.join(p['names'])} | {p['boundaryChunks']} | {p['drySafeSamples']} |")
 text+=['','## Explicit limits','',
 '- Timbermaw (native WMO 111596, placement 372018): all three branch pairs are bundled. Native short stair risers may face either direction and occur outside steps_* groups. Endpoints join the owning-zone components containing Bloodvenom Post/Emerald Sanctuary and Everlook; the numerically largest rectangle components belong to surrounding zones. Reputation may affect safe passage.',
 '- Winterspring–Hyjal cave (WMO 7960309, placement 70062766): the apparent Hyjal-side floor is at least 196 yards below terrain and has no supported outdoor Hyjal landing. It is not accepted as a through-exit.',
 '- Ironforge main entrance and Undercity static sewer entrance are bundled as native-floor corridors to permitted interior anchors. This certifies those entrance passages, not every corridor, wall or vertical layer throughout either city. Undercity elevators are separate transport work.',
 '- The Great Lift remains a transport connection, not a walking edge. Boats, zeppelins, trams and discovered flights already have separate navigation mechanisms and regression suites; none becomes an ordinary walking shortcut in this audit.',
 '- Gilneas ownership chunks are present in the snapshot but have no supported local map assignment in this dataset; no connection is fabricated through them.',
 '- Native WMO corridors retain their winding centerlines and require a dry outdoor landing or a separately proven interior floor anchor. Stair/floor/headroom checks are sampled native geometry, not a swept character collision certificate. Dynamic doors, faction restrictions and reputation requirements need live acceptance.',
 '- Routes use bounded local searches. A connected zone graph does not promise every point is reachable or that every far journey fits the work budget.',
 '- See `crossing-approaches-audit.md` for all retained approaches and `tools/data/crossing-handoff-review.json` for withheld handoffs. Native ownership adjacency without floor/terrain evidence remains unresolved, rather than being labelled an in-game wall.','']
 (ROOT/'docs/walking-coverage.md').write_text('\n'.join(text),encoding='utf8')
 print(len(edges),'links;',sum(a!=b for a,b in pairs),'zone pairs;',len(missing),'rejected/unproven ownership boundary pairs')

if __name__=='__main__':main()
